using System;public class Solution{public int MaxCoins(int[]a){int n=a.Length;int[]m=new int[n+2];m[0]=m[n+1]=1;for(int i=0;i<n;i++)m[i+1]=a[i];int[][]d=new int[n+2][];for(int i=0;i<n+2;i++)d[i]=new int[n+2];for(int len=1;len<=n;len++)for(int l=1;l+len-1<=n;l++){int r=l+len-1;for(int k=l;k<=r;k++)d[l][r]=Math.Max(d[l][r],d[l][k-1]+m[l-1]*m[k]*m[r+1]+d[k+1][r]);}return d[1][n];}}
